type Stack[T any] []T
func (s *Stack[T]) Push(v T) { *s = append(*s, v) }
func (s *Stack[T]) Pop() (T, bool) {
    if len(*s) == 0 { var zero T; return zero, false }
    v := (*s)[len(*s)-1]
    *s = (*s)[:len(*s)-1]
    return v, true
}
func main() {
    var s Stack[int]
    s.Push(10)
    s.Push(20)
    v, _ := s.Pop()
    fmt.Println(v)
}

