    var mu sync.Mutex
    s := []int{}
    var wg sync.WaitGroup
    for i := 0; i < 5; i++ {
        wg.Add(1)
        go func(n int) {
            defer wg.Done()
            mu.Lock()
            s = append(s, n)
            mu.Unlock()
        }(i)
    }
    wg.Wait()
